onClick:
{{
  (function() {
    // 1. Calcoliamo la differenza in giorni usando moment (libreria interna di Appsmith)
    const dataInizio = moment(DatePicker1.formattedDate);
    const dataFine = moment(DatePicker2.formattedDate);
    const giorniDiff = dataFine.diff(dataInizio, 'days');

    // 2. Controllo: Se la data Fine è PRIMA della data Inizio (es. ho sbagliato a selezionare)
    if (giorniDiff < 0) {
      showAlert('Errore: La "Data A" non può essere prima della "Data DA"', 'error');
    }
    // 3. Controllo: Se i giorni sono più di 30
    else if (giorniDiff > 30) {
      showAlert('Attenzione: Hai selezionato ' + giorniDiff + ' giorni. Il massimo è 30.', 'error');
    }
    // 4. Se tutto è ok, ESEGUI LA QUERY
    else {
      Query1.run(); // Sostituisci Query1 col nome della tua query se diverso
      showAlert('Ricerca avviata...', 'success');
    }
  })()
}}
